1. **Keychain:**
   - **iOS:** Используйте `react-native-keychain` для безопасного хранения сид-фразы.
   - **Android:** Используйте `KeyStore` для хранения сид-фразы.

2. **Место хранения:**
   - **iOS:**
     ```tsx
     import Keychain from 'react-native-keychain';

     const storeSeedPhrase = async (seedPhrase: string) => {
       await Keychain.setGenericPassword('seedPhrase', seedPhrase);
     };

     const retrieveSeedPhrase = async () => {
       const seedPhrase = await Keychain.getGenericPassword();
       return seedPhrase;
     };
     ```

   - **Android:**
     ```tsx
     import android.security.keystore.KeyProperties;
     import android.security.keystore.KeyGenParameterSpec;
     import android.security.keystore.KeyPermanentlyInvalidatedException;
     import android.security.keystore.KeyStore;
     import android.util.Base64;

     public class SeedPhraseStorage {
       private static final String KEY_ALIAS = "seedPhraseKey";

       public void storeSeedPhrase(String seedPhrase) {
         try {
           KeyStore keyStore = KeyStore.getInstance("AndroidKeyStore");
           keyStore.load(null);
           keyStore.setEntry(KEY_ALIAS, new SecretKeyGenerator(seedPhrase).generateKey(), new KeyGenParameterSpec.Builder(KEY_ALIAS, KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
               .setBlockModes(KeyProperties.BLOCK_MODE_CBC)
               .setUserAuthenticationRequired(true)
               .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_PKCS7)
               .build());
         } catch (Exception e) {
           e.printStackTrace();
         }
       }

       public String retrieveSeedPhrase() {
         try {
           KeyStore keyStore = KeyStore.getInstance("AndroidKeyStore");
           keyStore.load(null);
           SecretKey secretKey = (SecretKey) keyStore.getKey(KEY_ALIAS, null);
           if (secretKey == null) {
             throw new KeyPermanentlyInvalidatedException();
           }
           byte[] encryptedSeedPhrase = keyStore.getCertificateEntry(KEY_ALIAS).getEncoded();
           return Base64.encodeToString(encryptedSeedPhrase, Base64.DEFAULT);
         } catch (Exception e) {
           e.printStackTrace();
           return null;
         }
       }
     }
     ```

