1. **Установка необходимых библиотек:**

```sh
npm install @solana/web3.js @solana/spl-token @solana/wallet-adapter-react
```

2. **Настройка библиотек:**

```tsx
import { Connection, PublicKey, SystemProgram, Transaction } from '@solana/web3.js';
import { useWallet } from '@solana/wallet-adapter-react';

const connection = new Connection('https://solana-mainnet.bscscan.com', 'confirmed');

const useSolanaWallet = () => {
  const { publicKey, signTransaction } = useWallet();

  const sendTransaction = async (transaction: Transaction) => {
    if (!publicKey) {
      throw new Error('Public key not found');
    }

    const signedTransaction = await signTransaction(transaction, signTransaction);
    const result = await connection.sendRawTransaction(signedTransaction.serialize());
    return result;
  };

  return { publicKey, sendTransaction };
};

export default useSolanaWallet;
```

