JWT-аутентификация на NestJS можно реализовать с помощью модуля `@nestjs/jwt`. Вот как это можно сделать:

1. **Установка зависимости:**
   ```sh
   npm install @nestjs/jwt passport passport-jwt
   ```

2. **Настройка модуля JWT:**
   Создайте файл `auth.module.ts` в папке `auth`:

   ```ts
   import { Module } from '@nestjs/common';
   import { JwtModule } from '@nestjs/jwt';
   import { PassportModule } from '@nestjs/passport';
   import { AuthController } from './auth.controller';
   import { AuthService } from './auth.service';
   import { ConfigModule } from '@nestjs/config';

   @Module({
     imports: [
       ConfigModule,
       PassportModule,
       JwtModule.register({
         secret: process.env.JWT_SECRET_KEY,
         signOptions: { expiresIn: '1h' },
       }),
     ],
     controllers: [AuthController],
     providers: [AuthService],
   })
   export class AuthModule {}
   ```

3. **Настройка сервиса аутентификации:**
   Создайте файл `auth.service.ts`:

   ```ts
   import { Injectable } from '@nestjs/common';
   import { PassportStrategy } from '@nestjs/passport';
   import { Strategy as JwtStrategy, ExtractJwt } from 'passport-jwt';
   import { ConfigService } from '@nestjs/config';
   import { UsersService } from '../users/users.service';

   @Injectable()
   export class AuthService {
     constructor(
       private readonly configService: ConfigService,
       private readonly usersService: UsersService,
     ) {}

     async validateUser(payload: any) {
       const user = await this.usersService.findOne(payload.sub);
       return user;
     }
   }

   @Injectable()
   export class JwtStrategyService extends PassportStrategy(JwtStrategy) {
     constructor(private readonly authService: AuthService) {
       super({
         jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
         secretOrKey: process.env.JWT_SECRET_KEY,
       });
     }

     async validate(payload: any) {
       return this.authService.validateUser(payload);
     }
   }
   ```

